package com.cpf.education.online.validation.controller;
import com.cpf.education.online.validation.dto.MemberValidationCommand;import com.cpf.education.online.validation.service.MemberValidationService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.web.api.CpfRestController;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import java.util.Map;import org.springframework.web.bind.annotation.*;
/** Validation·표준 오류 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfRestController @RequestMapping("/edu/online/member-validation") public class MemberValidationController {private final MemberValidationService service;public MemberValidationController(MemberValidationService s){service=s;}@PostMapping @Operation(operationId="EDU_MEMBER_VALIDATION",summary="Validation·표준 오류") @CpfOnlineTransaction(operationId="EDU_MEMBER_VALIDATION",name="Validation·표준 오류 거래",description="Jakarta Validation, 업무 Validation, 400/404/409 표준 CPF 오류와 MessageSource를 사용한다.") public Map<String,String> validate(@Valid @RequestBody MemberValidationCommand c){return service.validate(c);}}
